{
  "tools": [
    {
      "name": "camera_screenshot",
      "title": "Camera Screenshot",
      "toolset": "scene",
      "description": "Render a camera in the scene and return it as an image. Give any CameraComponent's id or its game object's id, or nothing for the scene's main camera. Works in edit and play mode - editor_camera_screenshot shows the editor viewport instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "camera": {
            "type": "string",
            "description": "A CameraComponent id or its game object's id. Empty uses the scene's main camera."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "includeUi": {
            "type": "boolean",
            "description": "Include any UI the camera renders.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "editor_camera_screenshot",
      "title": "Editor Camera Screenshot",
      "toolset": "scene",
      "description": "Render what the editor scene camera sees and return it as an image - see the scene the way the viewport does. Move the view first with set_editor_camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "get_editor_camera",
      "title": "Get Editor Camera",
      "toolset": "scene",
      "description": "The editor scene camera's transform - where the scene viewport is looking from. Position, angles (pitch yaw roll) and field of view.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Position": {
            "type": "string"
          },
          "Angles": {
            "type": "string"
          },
          "FieldOfView": {
            "type": "number"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_screenshot",
      "title": "Screenshot",
      "toolset": "hammer",
      "description": "Render the map as Hammer's 3D view draws it and return the image - see what you've built. Renders from the main 3D view's camera unless you give a camera, which doesn't move the user's view. Aim it with hammer_focus_nodes or hammer_set_camera first, or pass position and lookAt.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "position": {
            "type": "string",
            "description": "Camera position as 'x,y,z'. Empty uses the 3D view's camera."
          },
          "angles": {
            "type": "string",
            "description": "Camera angles as 'pitch,yaw,roll'."
          },
          "lookAt": {
            "type": "string",
            "description": "A point to look at as 'x,y,z' - overrides angles."
          },
          "fieldOfView": {
            "type": "number",
            "description": "Field of view in degrees. 0 uses the 3D view's.",
            "minimum": 0,
            "maximum": 170,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_set_camera",
      "title": "Set Camera",
      "toolset": "hammer",
      "description": "Move a Hammer view's camera - give a position, and angles or a point to look at. Defaults to the 3D view the user used last. Returns the view's new state. To frame specific nodes instead, use hammer_focus_nodes.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "position": {
            "type": "string",
            "description": "Camera position as 'x,y,z'. Empty keeps the current one."
          },
          "angles": {
            "type": "string",
            "description": "View angles as 'pitch,yaw,roll'."
          },
          "lookAt": {
            "type": "string",
            "description": "A point to look at, as 'x,y,z' - overrides angles."
          },
          "view": {
            "type": "integer",
            "description": "Which view, by index from hammer_views. -1 for the main 3D view.",
            "default": -1
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Index": {
            "type": "integer"
          },
          "Is3D": {
            "type": "boolean"
          },
          "Active": {
            "type": "boolean"
          },
          "Position": {
            "type": "string"
          },
          "Angles": {
            "type": "string"
          },
          "FieldOfView": {
            "type": "number"
          },
          "Size": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_trace",
      "title": "Trace Ray",
      "toolset": "hammer",
      "description": "Trace a ray through the open map and report the first node it hits, where, and the surface normal - find the floor under a point, check what's in front of the camera, or probe where to place something. Traces Hammer's own geometry, so it works before the map is compiled.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          },
          "meshesOnly": {
            "type": "boolean",
            "description": "Only hit mesh geometry, ignoring entities and game objects.",
            "default": false
          },
          "skipToolsMaterials": {
            "type": "boolean",
            "description": "Don't hit tools materials like clip or trigger.",
            "default": false
          },
          "hitBackfaces": {
            "type": "boolean",
            "description": "Hit faces from behind too. A back face hit (the normal points along the ray) means the ray started inside something.",
            "default": false
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean"
          },
          "Position": {
            "type": "string"
          },
          "Normal": {
            "type": "string"
          },
          "Node": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "integer"
              },
              "Kind": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              },
              "ClassName": {
                "type": "string"
              },
              "Description": {
                "type": "string"
              },
              "Position": {
                "type": "string"
              },
              "Parent": {
                "type": "integer"
              },
              "GameObject": {
                "type": "string"
              },
              "Selected": {
                "type": "boolean"
              },
              "Visible": {
                "type": "boolean"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_views",
      "title": "Views",
      "toolset": "hammer",
      "description": "Hammer's views of the open map - each one's index, whether it's 3D or a 2D (orthographic) view, its camera position, angles and field of view, its size, and which one the user used last.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "perf_rendering",
      "title": "Rendering",
      "toolset": "perf",
      "description": "Rendering detail for the last frame: which renderer drew it, resolution and AA, the rendering issues the performance hub flags (draw calls, batching, texture pool), every scene system counter (draws, triangles, batches, material changes, culling, lights and shadows, texture pool, device report), the managed renderer's phases and draws when it rendered, and the active camera's post-processing layers.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "set_editor_camera",
      "title": "Set Editor Camera",
      "toolset": "scene",
      "description": "Move the editor scene camera. Give a position and/or angles - anything left empty keeps its current value. Returns the resulting transform.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "View angles as 'pitch,yaw,roll'."
          }
        },
        "required": []
      }
    },
    {
      "name": "ui_screenshot",
      "title": "Screenshot",
      "toolset": "ui",
      "description": "A screenshot of one panel, cropped to its screen rect, so you can look at what a panel actually draws without hunting for it in a full frame. Renders through the running scene's camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector. Empty uses the first root."
          },
          "padding": {
            "type": "integer",
            "description": "Extra pixels around the panel, for seeing shadows and outlines.",
            "minimum": 0,
            "maximum": 512,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    }
  ],
  "total": 128
}
